ipcMain.handle('select-book-source', async () => {
    if (!mainWindow)
        return null;
    const result = await dialog.showOpenDialog(mainWindow, {
        properties: ['openFile', 'multiSelections'],
        title: '选择绘本文件（PDF / 图片）',
        filters: [
            { name: 'Book Files', extensions: ['pdf', ...BOOK_IMAGE_EXTS.map((e) => e.slice(1))] },
            { name: 'PDF Documents', extensions: ['pdf'] },
            { name: 'Images', extensions: BOOK_IMAGE_EXTS.map((e) => e.slice(1)) },
        ],
    });
    if (result.canceled || result.filePaths.length === 0)
        return null;
    const filePaths = result.filePaths;
    const exts = filePaths.map((p) => path.extname(p).toLowerCase());
    const bookCount = exts.filter((e) => e === '.pdf').length;
    // 图片多选：按文件名自然序（page2 < page10）返回，交由渲染进程合成 PDF
    if (bookCount === 0) {
        if (!exts.every((e) => BOOK_IMAGE_EXTS.includes(e))) {
            return { error: `仅支持 PDF / 图片（${BOOK_IMAGE_EXTS.join(' ')}）` };
        }
        const sorted = [...filePaths].sort((a, b) => path.basename(a).localeCompare(path.basename(b), undefined, { numeric: true, sensitivity: 'base' }));
        try {
            const images = sorted.map((p) => ({ name: path.basename(p), buffer: fs.readFileSync(p) }));
            // 所在文件夹名常是更合适的默认项目标题（如 .../培生根茎英语-4/page-01.jpg）
            const dirPath = path.dirname(sorted[0]);
            const dirName = path.basename(dirPath);
            return {
                source: {
                    name: `${images.length} 张图片`,
                    images,
                    dirName: dirName && dirName !== path.sep ? dirName : undefined,
                },
            };
        }
        catch (e) {
            console.error('[select-book-source] read images error:', e);
            return { error: '读取图片失败，请重试' };
        }
    }
    if (filePaths.length > 1 || bookCount > 1) {
        return { error: 'PDF 请一次选择一个（图片才可多选，且不要与 PDF 混选）' };
    }
    const sourcePath = filePaths[0];
    const dir = path.dirname(sourcePath);
    const baseName = path.basename(sourcePath, path.extname(sourcePath));
    const audioExts = ['.mp3', '.wav', '.m4a', '.aac', '.flac', '.ogg', '.wma'];
    let audio;
    try {
        const entries = fs.readdirSync(dir);
        const lowerBase = baseName.toLowerCase();
        for (const entry of entries) {
            const ext = path.extname(entry).toLowerCase();
            if (!audioExts.includes(ext))
                continue;
            const entryBase = path.basename(entry, ext).toLowerCase();
            if (entryBase === lowerBase) {
                audio = { name: entry, buffer: fs.readFileSync(path.join(dir, entry)) };
                break;
            }
        }
    }
    catch (e) {
